/* Steam-authenticated race entries; private ACC identities never enter public listings. */
(() => {
 const en=document.documentElement.lang==='en',lang=en?'en':'fr',endpoint='https://twjpjzalyvbsdpbzhqln.supabase.co/functions/v1/race-registration';
 const word=(fr,english)=>en?english:fr;
 const el=(tag,text,cls)=>{const x=document.createElement(tag);if(text!=null)x.textContent=text;if(cls)x.className=cls;return x;};
 const token=()=>sessionStorage.getItem('atx-racing-session');
 const errors={team_name_required:word('Donnez un nom à votre équipage WGT.','Give your WGT crew a name.'),team_name_taken:word('Ce nom d’équipage est déjà utilisé pour cette course. Choisissez un nom distinct par voiture.','This crew name is already used for this race. Choose a distinct name per car.'),insufficient_coins:word('Vous avez besoin d’un Coin ATX pour confirmer votre inscription.','You need one ATX Coin to confirm your registration.'),acc_profile_required:word('Complétez votre identité ACC et votre numéro préféré dans votre profil pilote.','Complete your ACC identity and preferred number in your driver profile.'),event_full:word('La grille est complète.','The grid is full.'),race_number_taken:word('Ce numéro est déjà utilisé.','This number is already taken.'),crew_full:word('Cet équipage est complet.','This crew is full.'),invalid_invitation:word('Code d’équipage invalide.','Invalid crew code.'),captain_has_members:word('Les autres membres doivent se désinscrire avant le capitaine.','Other members must withdraw before the captain.'),confirmed_profile_required:word('Confirmez votre profil pilote avant de vous inscrire.','Confirm your driver profile before registering.'),registration_closed:word('Les inscriptions sont fermées.','Registration is closed.'),incomplete_sprint_crew:word('Un équipage Sprint doit compter deux pilotes avant l’export.','Sprint crews must contain two drivers before export.')};
 async function api(query='',body){const response=await fetch(endpoint+query,{method:body?'POST':'GET',headers:{Authorization:'Bearer '+token(),...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(18000)});if(!response.ok){const data=await response.json().catch(()=>({}));throw Error(errors[data.error]||word('Impossible de terminer cette opération. Vérifiez votre connexion Steam.','Unable to complete this action. Check your Steam sign-in.'));}if(body&&['register','withdraw','enable'].includes(body.action))window.ATX_CLEAR_PUBLIC_EVENTS?.();if(body&&['register','withdraw'].includes(body.action))window.dispatchEvent(new Event('atx-wallet-changed'));return response;}
 const field=(form,label,name,type='text',required=true)=>{const wrap=el('label',null,'profile-field'),input=el(type==='select'?'select':'input');input.name=name;if(type!=='select')input.type=type;input.required=required;wrap.append(el('span',label),input);form.append(wrap);return input;};
 const button=(label,fn)=>{const b=el('button',label,'pill');b.type='button';b.onclick=fn;return b;};
 document.addEventListener('atx:event-detail',async({detail:event})=>{
  if(event.simgrid_url||(!event.site_registration_enabled&&event.competition_code!=='ATXS'&&!(event.registered_count>0)))return;
  const panel=el('section',null,'admin-panel race-registration'),status=el('p',null,'form-status');status.setAttribute('role','status');panel.append(el('span','STEAM / ACC','eyebrow'),el('h2',word('Inscription sur le site','Website registration')),status);document.querySelector('#results')?.firstElementChild?.append(panel);
  if(!token()){const link=el('a',word('Me connecter avec Steam pour m’inscrire','Sign in with Steam to register'),'action');link.href=document.querySelector('meta[name=atx-base]')?.content||'/atxracing/';link.onclick=()=>{try{sessionStorage.setItem('atx-after-login',location.pathname+location.search);}catch{}};panel.append(link);return;}
  async function render(){try{
   const data=await (await api('?event='+encodeURIComponent(event.id))).json();panel.querySelectorAll('form,.registration-body').forEach(x=>x.remove());
   const box=el('div',null,'registration-body');panel.append(box);
   box.append(el('p',`${data.count} / ${data.event.max_drivers} `+word('voitures inscrites','cars registered')));
   box.append(el('p',word('Inscription : 1 Coin ATX. Annulation avant le départ : remboursement. Course terminée : remboursement après résultat officiel. Aucun débit en liste d’attente.','Registration: 1 ATX Coin. Cancel before the start for a refund. Finishing refunds your entry after official validation. No charge on the waiting list.'),'profile-note'));
   if(data.waitlist){box.append(el('p',data.waitlist.state==='offered'?word('Une place vous est réservée jusqu’au ','A place is reserved for you until ')+new Intl.DateTimeFormat(lang,{timeStyle:'short',timeZone:'Europe/Brussels'}).format(new Date(data.waitlist.offered_until)):word('Vous êtes en liste d’attente. Une place libérée vous sera réservée pendant 30 minutes ; confirmez-la ici ou depuis Mon paddock.','You are on the waiting list. A free place will be reserved for 30 minutes; confirm it here or from My paddock.')));box.append(button(word('Quitter la liste d’attente','Leave waiting list'),async()=>{try{await api('',{action:'withdraw',eventId:event.id});await render();}catch(e){status.textContent=e.message;}}));if(data.waitlist.state==='waiting')return;}
   if(data.entry){box.append(el('p',word('Vous êtes inscrit : voiture n° ','You are registered: car #')+data.entry.race_number+(data.entry.team_name?' · '+data.entry.team_name:'')));
    if(data.crew?.length){const crew=el('ul',null,'registration-crew');for(const member of data.crew)crew.append(el('li',[member.first_name,member.last_name,'('+member.short_name+')'].join(' ')));box.append(el('h3',word('Pilotes de la voiture','Drivers in this car')),crew);}
    const model=data.cars.find(car=>car.car_model_id===data.entry.car_model_id);if(model)box.append(el('p',model.name));
    if(data.entry.join_code&&event.format_code?.startsWith('WGT_')){box.append(el('p',word('Partagez ce code uniquement avec vos coéquipiers. Chaque pilote se connecte avec son propre compte Steam pour rejoindre la voiture.','Share this code only with your teammates. Each driver signs in with their own Steam account to join the car.')));const code=el('code',data.entry.join_code);box.append(code);}
    if(Date.parse(event.starts_at)>Date.now()&&!['cancelled','completed'].includes(event.status))box.append(button(word('Me désinscrire','Withdraw'),async()=>{try{await api('',{action:'withdraw',eventId:event.id});status.textContent='';await render();}catch(e){status.textContent=e.message;}}));return;}
   if(event.status!=='registration_open'||Date.parse(event.starts_at)<=Date.now()){box.append(el('p',errors.registration_closed));return;}
   if(!data.cars.length){box.append(el('p',word('L’organisateur prépare le catalogue des voitures ; les inscriptions ouvriront ensuite.','The organiser is preparing the car catalogue; registration will be available afterwards.')));return;}
   const profile=data.profile||{};if(!profile.complete){box.append(el('p',errors.acc_profile_required));const link=el('a',word('Compléter mon profil ACC','Complete my ACC profile'),'pill');link.href=(document.querySelector('meta[name="atx-base"]')?.content||'/atxracing/')+lang+'/acc/profile.html?complete=acc';box.append(link);return;}
   const form=el('form',null,'admin-form');box.append(form);form.append(el('p',[profile.acc_first_name,profile.acc_last_name,'('+profile.acc_short_name+')'].join(' '),'registration-identity'),el('p',word('Identité ACC reprise de votre profil. Pour la modifier, ouvrez votre profil pilote.','ACC identity from your profile. To change it, open your driver profile.'),'profile-note'));const edit=el('a',word('Modifier mon profil','Edit my profile'),'pill');edit.href=(document.querySelector('meta[name="atx-base"]')?.content||'/atxracing/')+lang+'/acc/profile.html?complete=acc';form.append(edit);
   const number=field(form,word('Numéro de voiture','Car number'),'raceNumber','number');number.min=0;number.max=999;number.step=1;number.value=profile.car_number??'';
   const car=el('fieldset',null,'registration-car-picker');car.append(el('legend',word('Choisissez votre GT3','Choose your GT3')),el('p',word('Sélectionnez une voiture que vous possédez dans ACC, y compris son DLC éventuel.','Choose a car you own in ACC, including its DLC if required.'),'profile-note'));const grid=el('div',null,'registration-car-grid');car.append(grid);form.append(car);
   for(const item of data.cars){const label=el('label',null,'registration-car-option'),radio=el('input');radio.type='radio';radio.name='carModelId';radio.value=item.car_model_id;radio.required=true;const preferred=profile.preferred_gt3;radio.checked=item.name===preferred;label.append(radio);if(/^[a-z0-9-]+\.webp$/.test(item.artwork_file||'')){const image=el('img');image.src=(document.querySelector('meta[name="atx-base"]')?.content||'/atxracing/')+'assets/gt3/thumbs/'+item.artwork_file;image.alt='';image.width=360;image.height=200;image.loading='lazy';image.decoding='async';label.append(image);}label.append(el('span',item.name));grid.append(label);}
   if(profile.preferred_gt3&&!data.cars.some(item=>item.name===profile.preferred_gt3))car.append(el('p',word('Votre voiture préférée ne figure pas au catalogue de cette course. Choisissez une voiture proposée.','Your preferred car is not in this race catalogue. Choose one of the available cars.'),'profile-note'));
   const carValue=()=>form.querySelector('[name=carModelId]:checked')?.value;

   const team=field(form,event.format_code?.startsWith('WGT_')?word('Nom distinct de votre équipage WGT','Distinct WGT crew name'):word('Nom de l’équipe · facultatif','Team name · optional'),'teamName','text',false);team.required=Boolean(event.format_code?.startsWith('WGT_'));team.maxLength=100;team.value=profile.team_name||'';
   let invite;if(event.format_code?.startsWith('WGT_')){form.append(el('p',word('Le capitaine choisit la voiture, le numéro et l’équipe, puis partage son code. Les coéquipiers rejoignent avec leur propre compte Steam et leur identité ACC. Sprint : 2 pilotes ; endurance : jusqu’à 6.','The captain chooses the car, number and team, then shares the crew code. Teammates join using their own Steam account and ACC identity. Sprint: 2 drivers; endurance: up to 6.'),'profile-note'));invite=field(form,word('Code pour rejoindre un équipage · facultatif','Code to join a crew · optional'),'joinCode','text',false);invite.oninput=()=>{const joining=!!invite.value.trim();number.required=!joining;number.disabled=joining;number.closest('label').hidden=joining;team.disabled=joining;team.required=!joining;team.closest('label').hidden=joining;car.hidden=joining;car.querySelectorAll('input').forEach(input=>{input.required=!invite.value.trim();input.disabled=!!invite.value.trim();});};}
   form.append(el('p',word('Votre Steam ID est repris automatiquement de votre connexion. Ces noms servent à l’entry list du serveur et restent accessibles à l’organisateur.','Your Steam ID comes automatically from your sign-in. These names are used in the server entry list and are accessible to the organiser.'),'profile-note'));
   const full=Number(data.count)>=Number(data.event.max_drivers)&&data.waitlist?.state!=='offered';const submit=el('button',full?word('Rejoindre la liste d’attente','Join waiting list'):word('Confirmer mon inscription · 1 Coin ATX','Confirm registration · 1 ATX Coin'),'action');submit.type='submit';form.append(submit);
   form.onsubmit=async e=>{e.preventDefault();submit.disabled=true;try{const result=await (await api('',{action:'register',eventId:event.id,raceNumber:Number(number.value),carModelId:Number(carValue()),teamName:team.value.trim(),joinCode:invite?.value.trim()||''})).json();status.textContent=result.waitlisted?word('Ajouté à la liste d’attente. Aucun Coin débité.','Added to the waiting list. No Coins charged.'):word('Inscription confirmée.','Registration confirmed.');await render();}catch(error){status.textContent=error.message;}finally{submit.disabled=false;}};
  }catch(error){status.textContent=error.message;}}
  await render();
 });
 document.addEventListener('atx:admin-render',async()=>{
  const root=document.querySelector('.admin-content');if(!root)return;const panel=el('section',null,'admin-panel');panel.append(el('h2',word('Inscriptions et entry lists ACC','Registrations and ACC entry lists')));root.append(panel);const status=el('p',null,'form-status');status.setAttribute('role','status');panel.append(status);
  try{const data=await (await api('?admin=1')).json();const select=el('select');select.setAttribute('aria-label',word('Course à gérer','Race to manage'));const eligible=data.events.filter(event=>!event.simgrid_url&&(event.competition_code==='ATXS'||event.site_registration_enabled));for(const event of eligible){const o=el('option',event['title_'+lang]||event.title_fr);o.value=event.id;select.append(o);}panel.append(el('p',word('Uniquement les courses avec inscription sur le site. Les courses SimGrid se gèrent sur SimGrid.','Only races with website registration. SimGrid races are managed on SimGrid.'),'profile-note'),select);if(!eligible.length)panel.append(el('p',word('Aucune course à gérer ici. Créez et publiez une course ATX Series pour la retrouver dans cet espace.','No races to manage here. Create and publish an ATX Series race to see it in this section.'),'profile-note'));
   const controls=el('div',null,'account-actions');panel.append(controls);

   controls.append(button(word('Activer les inscriptions sur le site','Enable website registration'),async()=>{try{await api('',{action:'enable',eventId:select.value,enabled:true});status.textContent=word('Inscriptions activées.','Registration enabled.');}catch(e){status.textContent=e.message;}}));
   controls.append(button(word('Fermer les inscriptions sur le site','Disable website registration'),async()=>{try{await api('',{action:'enable',eventId:select.value,enabled:false});status.textContent=word('Inscriptions désactivées.','Registration disabled.');}catch(e){status.textContent=e.message;}}));
   const exportFile=async format=>{try{const response=await api('?event='+encodeURIComponent(select.value)+'&export='+format);const blob=await response.blob(),url=URL.createObjectURL(blob),link=el('a');link.href=url;link.download=format==='json'?'entrylist.json':'suivi-inscriptions.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),10000);status.textContent=format==='json'?word('entrylist.json téléchargé. Installez-le dans le dossier de configuration actif du serveur ACC, puis redémarrez le serveur.','entrylist.json downloaded. Install it in the active ACC server configuration folder, then restart the server.'):word('Tableau de suivi téléchargé. Ce CSV ne peut pas servir d’entry list au serveur ACC.','Registration spreadsheet downloaded. This CSV cannot be used as an ACC server entry list.');}catch(e){status.textContent=e.message;}};
   controls.append(button(word('Télécharger l’entry list pour le serveur ACC','Download entry list for the ACC server'),()=>exportFile('json')));
   const tracking=el('details');tracking.append(el('summary',word('Suivi des inscriptions · tableur','Registration tracking · spreadsheet')),el('p',word('Pour Excel ou un tableur uniquement. Utilisez le bouton serveur ACC ci-dessus pour installer la grille sur le serveur.','For Excel or a spreadsheet only. Use the ACC server button above to install the grid on the server.'),'profile-note'),button(word('Télécharger le tableau CSV','Download CSV spreadsheet'),()=>exportFile('csv')));panel.append(tracking);tracking.hidden=!eligible.length;
   if(!eligible.length){select.hidden=true;controls.hidden=true;}
   panel.append(el('p',word('Le CSV facilite la gestion ; le JSON est le fichier entrylist attendu par ACC. Les identifiants Steam figurent uniquement dans ces exports administrateur.','CSV is for management; JSON is the entrylist file used by ACC. Steam IDs appear only in these administrator exports.'),'profile-note'));
   const form=el('form',null,'admin-form');panel.append(el('h3',word('Catalogue des modèles ACC','ACC model catalogue')),el('p',word('Renseignez le numéro officiel du modèle utilisé par votre serveur ACC. Aucun numéro n’est déduit du nom de la voiture.','Enter the official model number used by your ACC server. Numbers are never inferred from car names.'),'profile-note'),form);
   const name=field(form,word('Nom du modèle','Model name'),'name'),id=field(form,word('Identifiant du modèle ACC','ACC model ID'),'carModelId','number');name.maxLength=100;id.min=0;id.max=999;id.step=1;const save=el('button',word('Enregistrer le modèle','Save model'),'action');save.type='submit';form.append(save);
   const cars=el('p',data.cars.map(c=>c.name+' · '+c.car_model_id).join(' / '));panel.append(cars);
   form.onsubmit=async e=>{e.preventDefault();save.disabled=true;try{await api('',{action:'save_car',name:name.value.trim(),carModelId:Number(id.value)});status.textContent=word('Modèle enregistré.','Model saved.');cars.textContent+= (cars.textContent?' / ':'')+name.value.trim()+' · '+id.value;form.reset();}catch(error){status.textContent=error.message;}finally{save.disabled=false;}};
  }catch(error){status.textContent=error.message;}
 });
})();
